// ArcticTradeLanes.com — additive route for the restored static /funding and /advertise pages (2026-10-18).
// Paste into Zo's server.ts BEFORE the catch-all / 404 handler (and after /api, /.well-known, x402 routes,
// which stay untouched). Serves ./pages/[<lc>/]{funding,advertise}.html generated by build_pages.py.
// Only these two slugs (+ the 22 locale prefixes) are matched; every other path falls through unchanged.
const ATL_PAGE_LANGS = "ru|zh|ja|ko|el|de|nl|fr|es|it|pt|tr|ar|hi|vi|id|da|fi|sv|nb|is";
const ATL_PAGE_RE = new RegExp(`^/(?:(${ATL_PAGE_LANGS})/)?(funding|advertise)/?$`);
app.use(async (c, next) => {
  if (c.req.method !== "GET" && c.req.method !== "HEAD") return next();
  const m = c.req.path.match(ATL_PAGE_RE);
  if (!m) return next();
  const f = Bun.file(`./pages/${m[1] ? m[1] + "/" : ""}${m[2]}.html`);
  if (!(await f.exists())) return next();
  return new Response(c.req.method === "HEAD" ? null : f, {
    headers: { "Content-Type": "text/html; charset=UTF-8", "Cache-Control": "public, max-age=300", "X-ATL-Page": m[2] },
  });
});
